import subprocess, random

def oracle(data: bytes) -> bytes:
    p = subprocess.run(['./oracle'], input=data, capture_output=True)
    return bytes.fromhex(p.stdout.decode().strip())

S = bytes([oracle(bytes([b]))[0] for b in range(256)])
S0 = S[0]

def predict(data: bytes) -> bytes:
    n=len(data)
    return bytes((S[data[n-1-j]] + 50*n - 37*j - S0) % 256 for j in range(n))

random.seed(1)
fails=0
for trial in range(300):
    n=random.randint(0,60)
    d=bytes(random.randrange(256) for _ in range(n))
    if oracle(d)!=predict(d):
        fails+=1
        if fails<5: print("FAIL", d.hex(), oracle(d).hex(), predict(d).hex())
# longer lengths
for n in [100,255,256,257,500,1000]:
    d=bytes(random.randrange(256) for _ in range(n))
    if oracle(d)!=predict(d): fails+=1; print("FAIL len",n)
print("fails:",fails)

# dump table for solver
with open('/tmp/S.txt','w') as f:
    f.write(S.hex())
EOF
